/**
 * CostBreakdownWidget — mirrors LocationSearchInput/index.test.tsx's pattern
 * (mocks the data hook, tests rendering only). Do not edit this file to
 * make it pass — edit index.tsx.
 *
 * Run (Windows): npm test -- CostBreakdownWidget --watchAll=false
 */
import { render, screen } from "@testing-library/react";
import { ThemeProvider } from "@mui/material/styles";
import { MaterialUIControllerProvider } from "context";
import appTheme from "assets/theme";
import CostBreakdownWidget, { CostBreakdownWidgetProps } from "./index";

// MDBox/MDProgress read theme tokens from MaterialUIControllerProvider's
// context — same providers the real app mounts at its root (src/index.tsx).
function renderWidget(props: CostBreakdownWidgetProps) {
  return render(
    <MaterialUIControllerProvider>
      <ThemeProvider theme={appTheme}>
        <CostBreakdownWidget {...props} />
      </ThemeProvider>
    </MaterialUIControllerProvider>
  );
}

jest.mock("hooks/useHgvTollReport", () => ({
  useHgvTollReport: jest.fn(),
}));
// eslint-disable-next-line @typescript-eslint/no-var-requires
const { useHgvTollReport } = require("hooks/useHgvTollReport");

const REPORT = {
  period: { from: "2026-07-01", to: "2026-07-31" },
  total_toll_eur: 1245.3,
  total_km: 5012,
  avg_eur_per_km: 0.2484,
  groupBy: "vehicle",
  breakdown: [
    { key: "v1", label: "GV-082-B", total_toll_eur: 1000, total_km: 4000, task_count: 10, unmatched_count: 0 },
    { key: "v2", label: "GV-091-C", total_toll_eur: 245.3, total_km: 1012, task_count: 3, unmatched_count: 2 },
  ],
};

afterEach(() => {
  jest.clearAllMocks();
});

test("loading state shows the loading copy, no summary numbers", () => {
  useHgvTollReport.mockReturnValue({ data: null, isLoading: true, error: null });
  renderWidget({ from: "2026-07-01", to: "2026-07-31" });
  expect(screen.getByText(/Loading toll report/i)).toBeInTheDocument();
});

test("error state shows an error message, not a crash", () => {
  useHgvTollReport.mockReturnValue({ data: null, isLoading: false, error: new Error("boom") });
  renderWidget({ from: "2026-07-01", to: "2026-07-31" });
  expect(screen.getByText(/Could not load the toll report/i)).toBeInTheDocument();
});

test("empty breakdown shows the empty-state copy", () => {
  useHgvTollReport.mockReturnValue({
    data: { ...REPORT, breakdown: [] },
    isLoading: false,
    error: null,
  });
  renderWidget({ from: "2026-07-01", to: "2026-07-31" });
  expect(screen.getByText(/No completed tasks with toll data/i)).toBeInTheDocument();
});

test("renders the summary totals and every breakdown row's label and cost", () => {
  useHgvTollReport.mockReturnValue({ data: REPORT, isLoading: false, error: null });
  renderWidget({ from: "2026-07-01", to: "2026-07-31" });

  expect(screen.getByText("€1245.30")).toBeInTheDocument();
  expect(screen.getByText("5012.0 km")).toBeInTheDocument();
  expect(screen.getByText("€0.2484")).toBeInTheDocument();

  expect(screen.getByText("GV-082-B")).toBeInTheDocument();
  expect(screen.getByText("GV-091-C")).toBeInTheDocument();
  expect(screen.getByText(/€1000\.00/)).toBeInTheDocument();
  expect(screen.getByText(/€245\.30/)).toBeInTheDocument();
});

test("a non-zero unmatched_count across rows shows the unmatched note with the right count", () => {
  useHgvTollReport.mockReturnValue({ data: REPORT, isLoading: false, error: null });
  renderWidget({ from: "2026-07-01", to: "2026-07-31" });
  expect(screen.getByText(/2 tasks have no matching tariff/i)).toBeInTheDocument();
});

test("zero unmatched_count across rows -> no unmatched note", () => {
  useHgvTollReport.mockReturnValue({
    data: { ...REPORT, breakdown: REPORT.breakdown.map((r) => ({ ...r, unmatched_count: 0 })) },
    isLoading: false,
    error: null,
  });
  renderWidget({ from: "2026-07-01", to: "2026-07-31" });
  expect(screen.queryByText(/has no matching tariff/i)).not.toBeInTheDocument();
});

test("null avg_eur_per_km (no km at all) renders a dash, not a crash", () => {
  useHgvTollReport.mockReturnValue({
    data: { ...REPORT, avg_eur_per_km: null },
    isLoading: false,
    error: null,
  });
  renderWidget({ from: "2026-07-01", to: "2026-07-31" });
  expect(screen.getByText("—")).toBeInTheDocument();
});

test("passes from/to/groupBy through to the hook", () => {
  useHgvTollReport.mockReturnValue({ data: REPORT, isLoading: false, error: null });
  renderWidget({ from: "2026-07-01", to: "2026-07-31", groupBy: "driver" });
  expect(useHgvTollReport).toHaveBeenCalledWith("2026-07-01", "2026-07-31", "driver");
});

test("groupBy defaults to 'vehicle' when not passed", () => {
  useHgvTollReport.mockReturnValue({ data: REPORT, isLoading: false, error: null });
  renderWidget({ from: "2026-07-01", to: "2026-07-31" });
  expect(useHgvTollReport).toHaveBeenCalledWith("2026-07-01", "2026-07-31", "vehicle");
});
